func atomicWrite(path string, data []byte, mode fs.FileMode) (err error) {
	file, err := os.CreateTemp(filepath.Dir(path), "."+filepath.Base(path)+".semrel-*")
	if err != nil {
		return err
	}
	tempName := file.Name()
	closed := false
	defer func() {
		if !closed {
			if closeErr := file.Close(); err == nil && closeErr != nil {
				err = closeErr
			}
		}
		if err != nil {
			_ = os.Remove(tempName)
		}
	}()

	if err = file.Chmod(mode.Perm()); err != nil {
		return err
	}
	if _, err = file.Write(data); err != nil {
		return err
	}
	if err = file.Sync(); err != nil {
		return err
	}
	if err = file.Close(); err != nil {
		return err
	}
	closed = true
	return os.Rename(tempName, path)
}

func expandTemplate(value string, data TemplateData) string {
	replacements := map[string]string{
		"nextRelease.version": data.NextVersion,
		"lastRelease.version": data.CurrentVersion,
		"gitTag":              data.TagName,
		"tag":                 data.TagName,
		"channel":             data.Branch,
		"branch":              data.Branch,
		"date":                data.Date,
	}
	for key, replacement := range data.Variables {
		replacements[key] = replacement
	}
	for key, replacement := range replacements {
		value = strings.ReplaceAll(value, "${"+key+"}", replacement)
	}
	return value
}

func preserveLineEndings(value string, existing []byte) string {
	if !bytes.Contains(existing, []byte("\r\n")) {
		return value
	}
	withoutCRLF := bytes.ReplaceAll(existing, []byte("\r\n"), nil)
	if bytes.Contains(withoutCRLF, []byte("\n")) {
		return value
	}
	value = strings.ReplaceAll(value, "\r\n", "\n")
	return strings.ReplaceAll(value, "\n", "\r\n")
}

func splitList(raw string) StringList {
	parts := strings.FieldsFunc(raw, func(r rune) bool {
		return r == ',' || r == ';' || r == '\n'
	})
	result := make(StringList, 0, len(parts))
	for _, part := range parts {
		if value := strings.TrimSpace(part); value != "" {
			result = append(result, value)
		}
	}
	return result
}

func allEmpty(values []string) bool {
	for _, value := range values {
		if strings.TrimSpace(value) != "" {
			return false
		}
	}
	return true
}
